sources.InlineTouch.ets:
@Component
export struct InlineTouch {
  @State counter: number = 0
  build() {
    Row() { Button('tap').onTouch((event: TouchEvent) => {
      this.counter = event.touches.length
    })
      Button('later').onClick(() => {
        this.counter = 99
      })
    }
  }
}

